function mergeTimeline(channels) {
  const rows = [];
  for (const channel of channels) {
    if (channel.muted) continue;
    for (const entry of channel.entries) rows.push({ channel: channel.name, id: entry.id, atMs: entry.atMs, text: entry.text });
