  ];
  return Object.freeze({
    scan(record) { live.emit('parcel.scanned', readRecord(record)); },
    request(record) { live.emit('parcel.scan.requested', readRecord(record)); },
    legacyScan(record) { historical.emit('parcels.scanned', readRecord(record)); },
    manifest: panel.rows, requests: panel.requests, legacy: archive.rows, bays,
