function createChannel() {
  const listeners = new Map();
  return Object.freeze({
    on(topic, receive) {
      const group = listeners.get(topic) ?? new Set();
      group.add(receive);
      listeners.set(topic, group);
      return () => {
        group.delete(receive);
        if (!group.size) listeners.delete(topic);
      };
    },
    emit(topic, record) {
      for (const receive of [...(listeners.get(topic) ?? [])]) receive(record);
    },
  });
}

function readRecord(value) {
  if (!value || typeof value !== 'object' || typeof value.id !== 'string' ||
      !value.id.length || typeof value.value !== 'number' || !Number.isFinite(value.value)) {
    throw new TypeError('Expected a nonempty id and finite value');
  }
  return Object.freeze({ id: value.id, value: value.value });
}

function copyRows(rows) {
  return Array.from(rows, ([id, value]) => ({ id, value }));
}

export function createVisitorBoard() {
  const spaces = { live: createChannel(), archive: createChannel() };
  const stores = new Map();
  for (const route of VIEW_ROUTES) {
    const store = new Map();
    stores.set(route.key, store);
    spaces[route.space].on(route.topics.put, (record) => route.receive(store, record));
    spaces[route.space].on(route.topics.clear, (id) => store.delete(id));
  }
  const halls = VIEW_ROUTES.filter(route => route.group === 'hall').map(route => ({
    feed(record) { spaces.live.emit(route.topics.put, readRecord(record)); },
    forget(id) { spaces.live.emit(route.topics.clear, id); },
    peek(id) { return stores.get(route.key).get(id); },
  }));
  return Object.freeze({
    admit(record) { spaces.live.emit('visitor.admitted', readRecord(record)); },
    reserve(record) { spaces.live.emit('visitor.admission.requested', readRecord(record)); },
    importArchive(record) { spaces.archive.emit('visitors.admitted', readRecord(record)); },
    admissions() { return copyRows(stores.get('admissions')); },
    reservations() { return copyRows(stores.get('reservations')); },
    archive() { return copyRows(stores.get('archive')); },
    halls,
  });
}

