21 |       !value.id.length || typeof value.value !== 'number' || !Number.isFinite(value.value)) {
22 |     throw new TypeError('Expected a nonempty id and finite value');
23 |   }
24 |   return Object.freeze({ id: value.id, value: value.value });
25 | }
