94 |   #channel;
95 |   constructor(channel) {
96 |     this.#channel = channel;
97 |     const handlers = new Map([
98 |       ['zone.00.observed', (record) => this.#rows.set(record.id, record.value)],
99 |       ['zone.00.removed', (id) => this.#rows.delete(id)],
100 |     ]);
101 |     for (const [topic, receive] of handlers) {
102 |       channel.on(topic, receive);
103 |     }
104 |   }
105 |   feed(record) {
106 |     this.#channel.emit('zone.00.observed', readRecord(record));
107 |   }
108 |   forget(id) {
109 |     this.#channel.emit('zone.00.removed', id);
110 |   }
111 |   peek(id) {
112 |     return this.#rows.get(id);
113 |   }
114 | }
