    new Zone37(field),
    new Zone38(field),
    new Zone39(field),
    new Zone40(field),
    new Zone41(field),
    new Zone42(field)
  ];
  return Object.freeze({
    measure(record) { field.emit('probe.measured', readRecord(record)); },
    schedule(record) { field.emit('probe.measurement.queued', readRecord(record)); },
    service(record) { workshop.emit('probe.measurement', readRecord(record)); },
    readings() { return panel.readings(); },
    scheduled() { return panel.scheduled(); },
    serviceLog() { return service.rows(); },
    zones,
  });
}

