function attachLayer00(incoming, outgoing) {
  const tiles = new Map();
  incoming.watch((packet) => {
    if (packet.channel === 'worker:layer-00-ready') {
      outgoing.post({ channel: 'layer.00.presented', payload: packet.payload });
    }
    if (packet.channel === 'worker:layer-00-removed') {
      outgoing.post({ channel: 'layer.00.cleared', payload: packet.payload });
    }
  });
  outgoing.watch((packet) => {
    if (packet.channel === 'layer.00.presented') tiles.set(packet.payload.id, packet.payload.value);
    if (packet.channel === 'layer.00.cleared') tiles.delete(packet.payload);
  });
  return Object.freeze({
    feed(record) {
      incoming.post({ channel: 'worker:layer-00-ready', payload: readRecord(record) });
    },
    forget(id) {
      incoming.post({ channel: 'worker:layer-00-removed', payload: id });
    },
    peek(id) { return tiles.get(id); },
  });
}

