  { ref_id: "r14", document_id: "draft", blob_id: "b72", deleted: true },
  { ref_id: "r29", document_id: "handbook", blob_id: "b72", deleted: false },
  { ref_id: "r35", document_id: "notes", blob_id: "b81", deleted: true }
]
