export function resolveTheme(base, layers) {
  const result = new Map(Object.entries(base));
  for (const layer of layers) {
    for (const [key, value] of Object.entries(layer)) {
      if (value !== null) result.set(key, value);
    }
  }
  return Object.fromEntries(result);
}

export function resolveShortcuts(base, layers) {
  const result = new Map(Object.entries(base));
  for (const layer of layers) {
    for (const [key, value] of Object.entries(layer)) {
      if (value === null) result.delete(key);
      else result.set(key, value);
    }
  }
  return Object.fromEntries(result);
}

export function collectorOption(previous, incoming) {
