1|export class Hub {
2|  constructor() { this.listeners = new Map(); }
3|  on(topic, listener) {
4|    const entries = this.listeners.get(topic) ?? [];
5|    entries.push(listener);
6|    this.listeners.set(topic, entries);
7|  }
8|  publish(topic, payload) {
9|    for (const listener of this.listeners.get(topic) ?? []) listener(payload);
10|  }
11|}

