import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
export function update(path, content, mode) {
  if (mode === '--check') {
    if (readFileSync(path, 'utf8') !== content) throw new Error('mismatch: ' + path);
  } else if (mode === '--write') {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
  } else throw new Error('expected --write or --check');
}
export function json(path) { return JSON.parse(readFileSync(path, 'utf8')); }
export function encode(value) { return JSON.stringify(value, null, 2) + '\n'; }
```

