import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { json, update } from './io.mjs';
const [card, mode, ...extra] = process.argv.slice(2);
const route = json('cards.json').cards[card];
if (!route || extra.length) throw Error('usage: card --write/--check');
const template = await import(pathToFileURL(resolve(route.module)));
const original = readFileSync(route.output, 'utf8');
const open = '// <slot:' + route.slot + '>\n';
const close = '// </slot:' + route.slot + '>';
const start = original.indexOf(open);
const end = original.indexOf(close, start + open.length);
if (start < 0 || end < start || original.indexOf(open, start + open.length) >= 0 ||
    original.indexOf(close, end + close.length) >= 0) throw Error('slot structure');
const result = original.slice(0, start + open.length) + template.render() + original.slice(end);
update(route.output, result, mode);
```

